# Construct BIBD(16, 60, 15, 4, 3) using 3 copies of affine plane of order 4

# GF(4) arithmetic
# Elements: 0, 1, 2, 3 where 2=α, 3=α+1, α²=α+1

def gf4_add(a, b):
    return a ^ b  # XOR for GF(4) addition

def gf4_mul(a, b):
    if a == 0 or b == 0:
        return 0
    if a == 1:
        return b
    if b == 1:
        return a
    # 2*2=3, 2*3=1, 3*2=1, 3*3=2
    mul_table = [[0,0,0,0], [0,1,2,3], [0,2,3,1], [0,3,1,2]]
    return mul_table[a][b]

# Points: (x, y) mapped to 4*x + y
points = [(x, y) for x in range(4) for y in range(4)]

# Construct affine plane blocks
blocks = []

# Type 1: y = mx + c
for m in range(4):
    for c in range(4):
        block = []
        for x in range(4):
            y = gf4_add(gf4_mul(m, x), c)
            block.append(4*x + y)
        blocks.append(block)

# Type 2: x = c (vertical lines)
for c in range(4):
    block = []
    for y in range(4):
        block.append(4*c + y)
    blocks.append(block)

print(f"Number of blocks in affine plane: {len(blocks)}")
print(f"Blocks: {blocks}")

# Verify affine plane properties
# Check each block has size 4
for i, block in enumerate(blocks):
    assert len(block) == 4, f"Block {i} has size {len(block)}"

# Check each point appears in 5 blocks
from collections import Counter
point_counts = Counter()
for block in blocks:
    for p in block:
        point_counts[p] += 1

for p in range(16):
    assert point_counts[p] == 5, f"Point {p} appears in {point_counts[p]} blocks"

# Check each pair appears in exactly 1 block
pair_counts = Counter()
for block in blocks:
    for i in range(4):
        for j in range(i+1, 4):
            pair = tuple(sorted([block[i], block[j]]))
            pair_counts[pair] += 1

for pair, count in pair_counts.items():
    assert count == 1, f"Pair {pair} appears in {count} blocks"

print("Affine plane verified!")

# Now create BIBD by repeating each block 3 times
bibd_blocks = []
for block in blocks:
    for _ in range(3):
        bibd_blocks.append(block)

print(f"Number of blocks in BIBD: {len(bibd_blocks)}")

# Verify BIBD properties
# Check each block has size 4
for i, block in enumerate(bibd_blocks):
    assert len(block) == 4, f"Block {i} has size {len(block)}"

# Check each point appears in 15 blocks
point_counts = Counter()
for block in bibd_blocks:
    for p in block:
        point_counts[p] += 1

for p in range(16):
    assert point_counts[p] == 15, f"Point {p} appears in {point_counts[p]} blocks"

# Check each pair appears in exactly 3 blocks
pair_counts = Counter()
for block in bibd_blocks:
    for i in range(4):
        for j in range(i+1, 4):
            pair = tuple(sorted([block[i], block[j]]))
            pair_counts[pair] += 1

for pair, count in pair_counts.items():
    assert count == 3, f"Pair {pair} appears in {count} blocks"

print("BIBD verified!")

# Create incidence matrix
v = 16
b = 60
matrix = [[0]*b for _ in range(v)]

for j, block in enumerate(bibd_blocks):
    for i in block:
        matrix[i][j] = 1

# Flatten in row-major order
flat = []
for i in range(v):
    for j in range(b):
        flat.append(matrix[i][j])

print(f"Flat list length: {len(flat)}")
print(f"First 60 elements: {flat[:60]}")

# Verify row sums
for i in range(v):
    row_sum = sum(matrix[i])
    assert row_sum == 15, f"Row {i} sums to {row_sum}"

# Verify column sums
for j in range(b):
    col_sum = sum(matrix[i][j] for i in range(v))
    assert col_sum == 4, f"Column {j} sums to {col_sum}"

# Verify pairwise inner products
for i1 in range(v):
    for i2 in range(i1+1, v):
        inner = sum(matrix[i1][j] * matrix[i2][j] for j in range(b))
        assert inner == 3, f"Rows {i1},{i2} have inner product {inner}"

print("All verifications passed!")
print(f"Solution: {flat}")
